DECLARE
  v_caller TEXT := auth.jwt() ->> 'sub';
  v_match_id TEXT;
  v_owner TEXT;
  v_new_strikes INT;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id = v_caller AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'admin_only');
  END IF;

  SELECT match_id, creator_uid INTO v_match_id, v_owner FROM creator_result_flags WHERE id = p_flag_id AND status = 'open';
  IF v_match_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'flag_not_found_or_resolved'); END IF;

  UPDATE users u SET sky_diamonds = sky_diamonds + jr.entry_fee_paid
  FROM join_requests jr, matches m
  WHERE jr.match_id = v_match_id AND jr.user_id = u.id AND m.id = v_match_id AND m.entry_type = 'sky_diamond' AND jr.entry_fee_paid > 0;
  UPDATE users u SET coins = coins + jr.entry_fee_paid
  FROM join_requests jr, matches m
  WHERE jr.match_id = v_match_id AND jr.user_id = u.id AND m.id = v_match_id AND m.entry_type = 'coins' AND jr.entry_fee_paid > 0;

  /* SSOT (2026-09-23c): canonical ledger currency (plural). Amount UNCHANGED. */
  INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, ref_id)
  SELECT jr.user_id, CASE WHEN m.entry_type = 'sky_diamond' THEN 'sky_diamonds' ELSE m.entry_type END, 'credit', jr.entry_fee_paid, 'creator_match_voided_refund', v_match_id
  FROM join_requests jr JOIN matches m ON m.id = jr.match_id WHERE jr.match_id = v_match_id AND jr.entry_fee_paid > 0;

  UPDATE matches SET status = 'cancelled' WHERE id = v_match_id;
  UPDATE creator_matches SET commission_status = 'voided' WHERE match_id = v_match_id;

  UPDATE users SET creator_strikes = creator_strikes + 1 WHERE id = v_owner RETURNING creator_strikes INTO v_new_strikes;

  IF v_new_strikes >= 6 THEN
    UPDATE users SET creator_suspended_permanently = true, is_creator = false WHERE id = v_owner;
  ELSIF v_new_strikes >= 3 THEN
    UPDATE users SET creator_suspended_until = NOW() + INTERVAL '30 days' WHERE id = v_owner;
    -- FIX: correct column names (premium_level/premium_expires, not
    -- premium_tier/premium_expires_at which don't exist on this table).
    UPDATE users SET premium_level = 0, premium_expires = NULL WHERE id = v_owner;
  END IF;

  UPDATE creator_result_flags SET status = 'confirmed_cheat', resolved_at = NOW(), resolved_by = v_caller WHERE id = p_flag_id;

  INSERT INTO notifications(user_id, type, title, body)
  VALUES (v_owner, 'creator_strike', '⚠️ Match Voided — Cheating Confirmed',
    'Tumhara match "' || v_match_id || '" cheating ke wajah se void kar diya gaya. Strikes: ' || v_new_strikes || '/6.' ||
    CASE WHEN v_new_strikes >= 6 THEN ' Creator Program se permanently ban kar diya gaya.'
         WHEN v_new_strikes >= 3 THEN ' 30 din ke liye hosting suspend kar di gayi hai, aur Premium bhi cancel kar diya gaya hai.'
         ELSE '' END);

  RETURN jsonb_build_object('success', true, 'strikes', v_new_strikes);
END;

DECLARE
  v_admin_uid TEXT := auth.jwt() ->> 'sub';
  v_match_id  TEXT;
  v_pool      NUMERIC;
  v_sched     TIMESTAMPTZ;
  v_pt        TEXT;
  v_p4        NUMERIC;
BEGIN
  IF NOT COALESCE((SELECT is_admin FROM users WHERE id = v_admin_uid), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_admin');
  END IF;

  IF p_title IS NULL OR length(trim(p_title)) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_title');
  END IF;
  IF p_sponsor_name IS NULL OR length(trim(p_sponsor_name)) < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_sponsor_name');
  END IF;
  IF p_mode NOT IN ('solo','duo','squad') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_mode');
  END IF;
  IF p_max_slots < 2 OR p_max_slots > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_slot_count');
  END IF;
  IF p_first_prize < 0 OR p_second_prize < 0 OR p_third_prize < 0
     OR COALESCE(p_fourth_prize, 0) < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_prize');
  END IF;

  /* ✅ B11: prize type sirf do hi — 'cash' (real money, default) ya 'coin'.
     Purane/hand-typed values ('coins', 'inr', 'money', '₹', '🪙') bhi
     normalize ho jaate hain, taaki koi legacy caller toot na jaye; iske
     alawa kuch bhi bheja gaya to saaf error. */
  v_pt := lower(trim(COALESCE(p_prize_type, 'cash')));
  IF v_pt IN ('cash','inr','money','rupees','rupee','real','real_money','₹') THEN
    v_pt := 'cash';
  ELSIF v_pt IN ('coin','coins','🪙') THEN
    v_pt := 'coin';
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'invalid_prize_type');
  END IF;

  v_sched := COALESCE(p_scheduled_at, NOW() + INTERVAL '20 minutes');
  IF v_sched < NOW() + INTERVAL '5 minutes' THEN
    RETURN jsonb_build_object('success', false, 'error', 'schedule_too_soon');
  END IF;

  /* ✅ B11 FIX: 4th-10th (per player) ab asli me count hota hai — 7 players
     (4,5,6,7,8,9,10) × per-player amount. Pehle ye field save hi nahi hoti
     thi (admin bharta tha, DB me kuch nahi jaata tha). Pool ab hamesha = 1st
     + 2nd + 3rd + 7×4th-10th → user card ka "Total Pool" aur asli obligation
     kabhi alag nahi ho sakte. */
  v_p4   := COALESCE(p_fourth_prize, 0);
  v_pool := p_first_prize + p_second_prize + p_third_prize + (7 * v_p4);

  -- Sponsored matches are always free entry — sponsor funds the whole
  -- prize pool, exactly like the existing "Koi entry fee nahi, sirf
  -- free tournament!" sponsored cards already say.
  -- (name intentionally NOT listed — it's GENERATED ALWAYS AS (title))
  INSERT INTO matches (
    title, mode, entry_type, entry_fee, max_slots, filled_slots,
    prize_pool, first_prize, second_prize, third_prize, prize_type,
    map, status, scheduled_at, is_sponsored, room_status
  ) VALUES (
    p_title, p_mode, 'free', 0, p_max_slots, 0,
    v_pool, p_first_prize, p_second_prize, p_third_prize, v_pt,
    p_map, 'upcoming', v_sched, true, 'pending'
  ) RETURNING id INTO v_match_id;

  INSERT INTO sponsored_tournaments (
    title, sponsor_name, prize_pool, prize_type, entry_type, status,
    match_id, description,
    prizes
  ) VALUES (
    p_title, p_sponsor_name, v_pool, v_pt, 'free', 'active',
    v_match_id, p_description,
    jsonb_build_object('first', p_first_prize, 'second', p_second_prize,
                       'third', p_third_prize, 'fourthToTenth', v_p4)
  );

  RETURN jsonb_build_object('success', true, 'match_id', v_match_id,
                            'prize_type', v_pt, 'prize_pool', v_pool);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;

DECLARE
  v_caller TEXT := auth.jwt() ->> 'sub';
  v_match_id TEXT;
  v_owner TEXT;
  v_per_kill NUMERIC;
  v_entry_type TEXT;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id = v_caller AND is_admin = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'admin_only');
  END IF;

  SELECT match_id, creator_uid INTO v_match_id, v_owner FROM creator_result_flags WHERE id = p_flag_id AND status = 'open';
  IF v_match_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'flag_not_found_or_resolved'); END IF;

  SELECT per_kill_prize, entry_type INTO v_per_kill, v_entry_type FROM matches WHERE id = v_match_id;

  -- Legit — pay out same as the normal auto-approve path would have.
  IF v_per_kill > 0 THEN
    IF v_entry_type = 'coins' THEN
      UPDATE users u SET coins = coins + (jr.kills * v_per_kill)
      FROM join_requests jr WHERE jr.match_id = v_match_id AND jr.user_id = u.id AND jr.kills > 0;
    ELSE
      UPDATE users u SET sky_diamonds = sky_diamonds + (jr.kills * v_per_kill)
      FROM join_requests jr WHERE jr.match_id = v_match_id AND jr.user_id = u.id AND jr.kills > 0;
    END IF;
    INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, ref_id)
    SELECT user_id, v_entry_type, 'credit', kills * v_per_kill, 'creator_match_prize', v_match_id
    FROM join_requests WHERE match_id = v_match_id AND kills > 0;
  END IF;

  UPDATE matches SET status = 'completed' WHERE id = v_match_id;
  PERFORM finalize_creator_commission(v_match_id);

  UPDATE creator_result_flags SET status = 'dismissed', resolved_at = NOW(), resolved_by = v_caller WHERE id = p_flag_id;

  RETURN jsonb_build_object('success', true);
END;

DECLARE
  v_match RECORD; v_jr RECORD; v_refund_count INT := 0; v_currency TEXT;
  v_caller TEXT := auth.jwt() ->> 'sub';
BEGIN
  IF v_caller IS NULL OR NOT COALESCE((SELECT is_admin FROM users WHERE id = v_caller), false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_AUTHORIZED');
  END IF;
  SELECT * INTO v_match FROM matches WHERE id = p_match_id FOR UPDATE;
  IF v_match.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'MATCH_NOT_FOUND');
  END IF;
  IF v_match.status = 'cancelled' THEN
    RETURN jsonb_build_object('ok', true, 'refund_count', 0, 'already_cancelled', true);
  END IF;
  FOR v_jr IN
    SELECT * FROM join_requests
    WHERE match_id = p_match_id
      AND status NOT IN ('cancelled','refunded','rejected')
      AND COALESCE(entry_fee_paid, 0) > 0
    FOR UPDATE
  LOOP
    /* ✅ MATCH-FLOW-E2E FIX (2026-10-30): green_diamond entry ka refund SKY
       wallet me ja raha tha (entry_type='coin' sirf singular match karta tha,
       baaki sab ELSE→sky). Live proof: run 40986675005 MF30 tx currency. */
    /* ✅ D87: GD-entry join rows par fee charged hi nahi hoti — refund skip */
    IF COALESCE(v_jr.entry_type,'') IN ('green_diamond','greendiamond','green') THEN
      UPDATE join_requests SET status = 'refunded' WHERE id = v_jr.id;
      CONTINUE;
    END IF;
    v_currency := CASE WHEN COALESCE(v_jr.entry_type,'') IN ('coin','coins') THEN 'coins'
                       ELSE 'sky_diamonds' END;
    IF v_currency = 'coins' THEN
      UPDATE users SET coins = COALESCE(coins,0) + v_jr.entry_fee_paid WHERE id = v_jr.user_id;
    ELSE
      UPDATE users SET sky_diamonds = COALESCE(sky_diamonds,0) + v_jr.entry_fee_paid WHERE id = v_jr.user_id;
    END IF;
    INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, ref_id, status)
    VALUES (v_jr.user_id, v_currency, 'credit', v_jr.entry_fee_paid, 'match_cancelled_refund', p_match_id, 'approved');
    UPDATE join_requests SET status = 'refunded' WHERE id = v_jr.id;
    INSERT INTO notifications(user_id, type, title, body, is_read, created_at, ref_id)
    VALUES (v_jr.user_id, 'refund', '💰 Match Cancelled — Refund',
            CHR(34)||COALESCE(v_match.name, v_match.title, p_match_id)||CHR(34)||' cancel ho gaya. Aapka entry fee wapas kar diya gaya hai.',
            false, NOW(), p_match_id)
    ON CONFLICT DO NOTHING;
    v_refund_count := v_refund_count + 1;
  END LOOP;
  UPDATE join_requests SET status = 'cancelled'
  WHERE match_id = p_match_id AND status NOT IN ('cancelled','refunded','rejected');
  UPDATE creator_commissions SET status = 'cancelled', updated_at = NOW()
  WHERE match_id = p_match_id AND status = 'hold';
  UPDATE matches SET filled_slots = GREATEST(
    filled_slots - COALESCE((SELECT SUM(CASE
      WHEN mode IN ('duo','squad') AND COALESCE(captain_uid, user_id) <> user_id THEN 0
      WHEN mode = 'duo' THEN 2
      WHEN mode = 'squad' THEN 4
      ELSE 1 END)
    FROM join_requests
    WHERE match_id = p_match_id AND status IN ('cancelled','refunded')), 0), 0)
  WHERE id = p_match_id;
  UPDATE matches SET status = 'cancelled', cancelled_at = NOW(), cancelled_by = v_caller
  WHERE id = p_match_id;
  RETURN jsonb_build_object('ok', true, 'refund_count', v_refund_count);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;

DECLARE
  v_caller TEXT := auth.jwt() ->> 'sub';
  v_jr RECORD;
  v_match RECORD;
  v_col TEXT;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  SELECT * INTO v_jr FROM join_requests WHERE id = p_join_id FOR UPDATE;
  IF v_jr IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Join request not found');
  END IF;

  IF v_jr.user_id <> v_caller THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not your entry');
  END IF;

  IF v_jr.status = 'refunded' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already refunded');
  END IF;

  SELECT status INTO v_match FROM matches WHERE id = v_jr.match_id;
  IF v_match IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Match not found');
  END IF;

  IF v_match.status NOT IN ('cancelled', 'canceled') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Match is not cancelled');
  END IF;

  IF COALESCE(v_jr.entry_fee_paid, 0) <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Nothing to refund', 'refunded', 0);
  END IF;

  /* ✅ MATCH-FLOW-E2E FIX (2026-10-30): green_diamond refund green wallet me. */
  v_col := CASE WHEN v_jr.entry_type IN ('coin','coins') THEN 'coins'
                WHEN v_jr.entry_type IN ('green_diamond','greendiamond','green') THEN 'green_diamonds'
                ELSE 'sky_diamonds' END;

  EXECUTE format('UPDATE users SET %I = COALESCE(%I, 0) + $1 WHERE id = $2', v_col, v_col)
    USING v_jr.entry_fee_paid, v_caller;

  UPDATE join_requests SET status = 'refunded' WHERE id = p_join_id;

  UPDATE matches SET filled_slots = GREATEST(filled_slots - CASE
    WHEN v_jr.mode IN ('duo','squad') AND COALESCE(v_jr.captain_uid, v_jr.user_id) <> v_jr.user_id THEN 0
    WHEN v_jr.mode = 'duo' THEN 2
    WHEN v_jr.mode = 'squad' THEN 4
    ELSE 1 END, 0)
  WHERE id = v_jr.match_id;

  INSERT INTO wallet_transactions (user_id, currency, txn_type, amount, reason, ref_id)
  VALUES (v_caller, v_col, 'credit', v_jr.entry_fee_paid, 'match_refund', v_jr.match_id);

  RETURN jsonb_build_object('success', true, 'refunded', v_jr.entry_fee_paid, 'currency', v_col);
END;

declare v_uid text;
begin
  v_uid := auth.jwt() ->> 'sub';
  if v_uid is null then
    return jsonb_build_object('success', false, 'error', 'Not authorized');
  end if;
  if p_uid is not null and p_uid <> v_uid then
    return jsonb_build_object('success', false, 'error', 'actor mismatch');
  end if;
  return public.claim_match_refund_inner(p_join_id, v_uid);
end

DECLARE
  /* ✅ BUG FIX (2026-10-06, A11): ऐप का Supabase client सिर्फ़ ANON key से बनता
     है (login Firebase ka hai), इसलिए auth.jwt()->>'sub' NULL aata hai aur ye
     function hamesha 'Not authorized' lautata tha — yani match cancel hone par
     user kabhi refund claim hi nahi kar sakta tha (aur isliye transaction
     history me refund dikhta hi nahi tha).
     Ab: identity pehle auth se, warna p_uid se — par refund SIRF usi join
     request par ho sakta hai jiska user_id = caller ho, isliye koi doosre ka
     paisa nahi khinch sakta. Baki saari shartein (match cancelled hona,
     pehle refund na hua ho, entry_fee_paid > 0) waisi hi hain. */
  v_caller TEXT := COALESCE(auth.jwt() ->> 'sub', NULLIF(btrim(p_uid), ''));
  v_jr RECORD;
  v_match RECORD;
  v_col TEXT;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  SELECT * INTO v_jr FROM join_requests WHERE id = p_join_id FOR UPDATE;
  IF v_jr IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Join request not found');
  END IF;

  IF v_jr.user_id <> v_caller THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not your entry');
  END IF;

  IF v_jr.status = 'refunded' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already refunded');
  END IF;

  SELECT status INTO v_match FROM matches WHERE id = v_jr.match_id;
  IF v_match IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Match not found');
  END IF;

  IF v_match.status NOT IN ('cancelled', 'canceled') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Match is not cancelled');
  END IF;

  /* ✅ D87: GD entry abolished — GD-entry joins par fee kabhi charged
     hi nahi hoti, isliye refund bhi nahi. */
  IF COALESCE(v_jr.entry_type,'') IN ('green_diamond','greendiamond','green') THEN
    RETURN jsonb_build_object('success', false, 'error', 'GD entry abolished - no fee charged', 'refunded', 0);
  END IF;

  IF COALESCE(v_jr.entry_fee_paid, 0) <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Nothing to refund', 'refunded', 0);
  END IF;

  /* ✅ D87: GD-entry refund impossible (fee kabhi charged hi nahi hoti). */
  v_col := CASE WHEN v_jr.entry_type IN ('coin','coins') THEN 'coins'
                ELSE 'sky_diamonds' END;

  EXECUTE format('UPDATE users SET %I = COALESCE(%I, 0) + $1 WHERE id = $2', v_col, v_col)
    USING v_jr.entry_fee_paid, v_caller;

  UPDATE join_requests SET status = 'refunded' WHERE id = p_join_id;

  UPDATE matches SET filled_slots = GREATEST(filled_slots - CASE
    WHEN v_jr.mode IN ('duo','squad') AND COALESCE(v_jr.captain_uid, v_jr.user_id) <> v_jr.user_id THEN 0
    WHEN v_jr.mode = 'duo' THEN 2
    WHEN v_jr.mode = 'squad' THEN 4
    ELSE 1 END, 0)
  WHERE id = v_jr.match_id;

  /* txn_type 'credit' hi rakha gaya hai (baaki app isi par credit samajhta
     hai); 'match_refund' reason se UI ise refund ke roop me dikhata hai */
  INSERT INTO wallet_transactions (user_id, currency, txn_type, amount, reason, ref_id)
  VALUES (v_caller, v_col, 'credit', v_jr.entry_fee_paid, 'match_refund', v_jr.match_id);

  /* ✅ A11: user ko notification bhi — pehle refund ka koi sandesh nahi aata
     tha, isliye paisa wapas aane ka pata hi nahi chalta tha */
  INSERT INTO public.notifications (user_id, type, title, body, ref_id)
  VALUES (v_caller, 'refund', '💰 Refund mil gaya',
          'Aapka entry ' || v_jr.entry_fee_paid || ' ' ||
          CASE WHEN v_col = 'coins' THEN 'coins' ELSE 'sky diamonds' END ||
          ' wapas aa gaya (match refund).',
          v_jr.match_id)
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('success', true, 'refunded', v_jr.entry_fee_paid, 'currency', v_col);
END;

DECLARE
  v_caller      TEXT := auth.jwt() ->> 'sub';
  v_is_service  BOOLEAN := (current_setting('role', true) = 'service_role');
  v_is_admin    BOOLEAN;
  v_m           RECORD;
  v_mr          RECORD;
  v_jr          RECORD;
  v_currency    TEXT := 'coins';
  v_curr_label  TEXT := 'Coins';
  v_first       NUMERIC; v_second NUMERIC; v_third NUMERIC; v_perk NUMERIC;
  v_old_rank    INT; v_old_kills INT;
  v_new_rank    INT; v_new_kills INT;
  v_rank_prize  NUMERIC; v_kill_prize NUMERIC;
  v_old_prize   NUMERIC; v_new_prize NUMERIC;
  v_target      TEXT;
  v_delta       NUMERIC;
  v_name        TEXT;
BEGIN
  /* ── Authorization ── */
  IF NOT v_is_service THEN
    IF v_caller IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Admin only');
    END IF;
    SELECT is_admin INTO v_is_admin FROM users WHERE id = v_caller;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Admin only');
    END IF;
  END IF;

  IF p_match_id IS NULL OR p_user_id IS NULL OR p_user_id = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'match_id/user_id required');
  END IF;

  /* match lock + business prize params (server-authoritative) */
  SELECT * INTO v_m FROM matches WHERE id = p_match_id FOR UPDATE;
  IF v_m.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'MATCH_NOT_FOUND');
  END IF;
  IF v_m.result_published_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'RESULT_NOT_PUBLISHED');
  END IF;

  v_name   := COALESCE(v_m.name, v_m.title, p_match_id);
  v_first  := COALESCE(v_m.first_prize, 0);
  v_second := COALESCE(v_m.second_prize, 0);
  v_third  := COALESCE(v_m.third_prize, 0);
  v_perk   := COALESCE(v_m.per_kill_prize, 0);

  /* currency mapping — publish_match_results jaisa hi */
  IF COALESCE(v_m.prize_type,'') IN ('green_diamond','greenDiamond') THEN
    v_currency := 'green_diamonds'; v_curr_label := 'Green Diamonds';
  ELSIF COALESCE(v_m.prize_type,'') IN ('sky','sky_diamond','skyDiamond') THEN
    v_currency := 'sky_diamonds'; v_curr_label := 'Sky Diamonds';
  ELSIF COALESCE(v_m.prize_type,'') IN ('coin','cash') THEN
    v_currency := 'coins'; v_curr_label := 'Coins';
  ELSE
    IF v_m.entry_type IN ('paid','sky_diamond','skyDiamond') THEN
      v_currency := 'green_diamonds'; v_curr_label := 'Green Diamonds';
    END IF;
  END IF;

  /* authoritative published result row + join row */
  SELECT * INTO v_mr FROM match_results
    WHERE match_id = p_match_id AND user_id = p_user_id FOR UPDATE;
  IF v_mr.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'RESULT_NOT_FOUND');
  END IF;

  SELECT * INTO v_jr FROM join_requests
    WHERE match_id = p_match_id AND user_id = p_user_id;
  IF v_jr.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'JOIN_NOT_FOUND');
  END IF;

  v_old_rank  := COALESCE(v_mr.rank, 0);
  v_old_kills := COALESCE(v_mr.kills, 0);
  v_new_rank  := COALESCE(p_rank, v_old_rank);
  v_new_kills := COALESCE(p_kills, v_old_kills);

  v_rank_prize := CASE WHEN v_new_rank = 1 THEN v_first
                       WHEN v_new_rank = 2 THEN v_second
                       WHEN v_new_rank = 3 THEN v_third
                       ELSE 0 END;
  v_kill_prize := v_new_kills * v_perk;

  /* prize: server compute by default; manual override sirf admin-checked
     path par (yahan admin check upar ho chuka + service) */
  v_old_prize := COALESCE(v_mr.rank_prize, 0) + (COALESCE(v_old_kills,0) * v_perk);
  IF p_manual_amount IS NOT NULL THEN
    v_new_prize := GREATEST(p_manual_amount, 0);
  ELSE
    v_new_prize := v_rank_prize + v_kill_prize;
  END IF;

  /* captain_pays member → paisa captain ko (publish jaisa aggregation) */
  v_target := p_user_id;
  IF v_jr.fee_type = 'captain_pays'
     AND v_jr.captain_uid IS NOT NULL
     AND v_jr.captain_uid <> p_user_id THEN
    v_target := v_jr.captain_uid;
  END IF;

  v_delta := v_new_prize - v_old_prize;

  /* ── wallet delta on target (credit/debit, floor 0) ── */
  IF v_delta <> 0 THEN
    IF v_currency = 'coins' THEN
      UPDATE users SET coins = GREATEST(COALESCE(coins,0) + v_delta, 0),
                       total_winnings = GREATEST(COALESCE(total_winnings,0) + v_delta, 0)
      WHERE id = v_target;
    ELSIF v_currency = 'sky_diamonds' THEN
      UPDATE users SET sky_diamonds = GREATEST(COALESCE(sky_diamonds,0) + v_delta, 0),
                       total_winnings = GREATEST(COALESCE(total_winnings,0) + v_delta, 0)
      WHERE id = v_target;
    ELSE
      UPDATE users SET green_diamonds = GREATEST(COALESCE(green_diamonds,0) + v_delta, 0),
                       total_winnings = GREATEST(COALESCE(total_winnings,0) + v_delta, 0)
      WHERE id = v_target;
    END IF;

    INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, status, ref_id, created_at)
    VALUES (v_target, v_currency,
            CASE WHEN v_delta > 0 THEN 'correction_credit' ELSE 'correction_debit' END,
            ABS(v_delta), 'result_correction', 'approved', p_match_id, NOW());

    INSERT INTO notifications(user_id, type, title, body, is_read, created_at, ref_id)
    VALUES (v_target, 'correction', '🔧 Result Correction',
            v_name || ' — ' || ABS(v_delta) || ' ' || v_curr_label || ' ' ||
            CASE WHEN v_delta > 0 THEN 'add kiya gaya.' ELSE 'adjust kiya gaya.' END,
            false, NOW(), p_match_id);
  END IF;

  /* ── kills delta on the player (stats) ── */
  IF v_new_kills <> COALESCE(v_old_kills, 0) THEN
    UPDATE users SET total_kills = GREATEST(COALESCE(total_kills,0)
              + (v_new_kills - COALESCE(v_old_kills,0)), 0)
    WHERE id = p_user_id;
  END IF;

  /* ── match_results (authoritative) ── */
  /* publish_match_results kI tarah: captain_pays member kI row ka prize 0
     rehta hai (paisa captain ko aggregate hota hai) — prize + prize_earned
     dono byte-consistent. */
  UPDATE match_results SET
    placement   = v_new_rank,
    kills       = v_new_kills,
    rank        = v_new_rank,
    kill_prize  = v_kill_prize,
    rank_prize  = v_rank_prize,
    prize_earned = CASE WHEN v_jr.fee_type = 'captain_pays'
                         AND v_jr.captain_uid IS NOT NULL
                         AND v_jr.captain_uid <> p_user_id
                        THEN 0 ELSE v_new_prize END,
    prize       = CASE WHEN v_jr.fee_type = 'captain_pays'
                         AND v_jr.captain_uid IS NOT NULL
                         AND v_jr.captain_uid <> p_user_id
                        THEN 0 ELSE v_new_prize END
  WHERE match_id = p_match_id AND user_id = p_user_id;

  /* ── join_requests final state ── */
  UPDATE join_requests SET
    status = 'completed', placement = v_new_rank,
    prize_earned = CASE WHEN v_jr.fee_type = 'captain_pays'
                         AND v_jr.captain_uid IS NOT NULL
                         AND v_jr.captain_uid <> p_user_id
                        THEN 0 ELSE v_new_prize END,
    kills = v_new_kills
  WHERE match_id = p_match_id AND user_id = p_user_id;

  /* ── admin_actions audit log ── */
  INSERT INTO admin_actions(action, match_id, user_id, user_name, new_rank, new_kills, new_prize, delta, created_at)
  VALUES ('result_correction', p_match_id, p_user_id,
          NULLIF(p_user_name, ''), v_new_rank, v_new_kills, v_new_prize, v_delta, NOW());

  RETURN jsonb_build_object(
    'ok', true,
    'match_id', p_match_id,
    'user_id', p_user_id,
    'target', v_target,
    'currency', v_currency,
    'old_rank', v_old_rank, 'new_rank', v_new_rank,
    'old_kills', v_old_kills, 'new_kills', v_new_kills,
    'old_prize', v_old_prize, 'new_prize', v_new_prize,
    'delta', v_delta);
END;

DECLARE
  v_uid TEXT := auth.jwt() ->> 'sub';
  v_is_creator BOOLEAN;
  v_prem_level INT;
  v_prem_expires TIMESTAMPTZ;
  v_open_count INT;
  v_match_id TEXT;
  v_max_fee CONSTANT NUMERIC := 50;
  v_max_slots CONSTANT INT := 100;
  v_max_open CONSTANT INT := 3;
  v_creator_ign TEXT;
  v_follower_count INT;
  v_comm_pct NUMERIC;
  v_prize_pool NUMERIC;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;

  SELECT is_creator, ign, premium_level, premium_expires INTO v_is_creator, v_creator_ign, v_prem_level, v_prem_expires FROM users WHERE id = v_uid;
  IF NOT COALESCE(v_is_creator, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_a_creator');
  END IF;
  IF COALESCE(v_prem_level, 0) <= 0 OR v_prem_expires IS NULL OR v_prem_expires < NOW() THEN
    RETURN jsonb_build_object('success', false, 'error', 'premium_required');
  END IF;

  IF EXISTS(SELECT 1 FROM users WHERE id = v_uid AND (creator_suspended_permanently = true OR (creator_suspended_until IS NOT NULL AND creator_suspended_until > NOW()))) THEN
    RETURN jsonb_build_object('success', false, 'error', 'creator_suspended');
  END IF;

  /* ✅ BUG FIX (2026-10-04): green_diamond entry bhi allow (price type selection) */
  IF p_entry_type NOT IN ('coins', 'sky_diamond') THEN  /* D87: GD entry abolished */
    RETURN jsonb_build_object('success', false, 'error', 'invalid_entry_type');
  END IF;
  IF p_entry_fee IS NULL OR p_entry_fee < 1 OR p_entry_fee > v_max_fee THEN
    RETURN jsonb_build_object('success', false, 'error', 'entry_fee_out_of_range', 'max', v_max_fee);
  END IF;
  IF p_max_slots IS NULL OR p_max_slots < 2 OR p_max_slots > v_max_slots THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_slot_count', 'max', v_max_slots);
  END IF;
  IF p_scheduled_at IS NULL OR p_scheduled_at < NOW() + INTERVAL '20 minutes' THEN
    RETURN jsonb_build_object('success', false, 'error', 'schedule_too_soon');
  END IF;
  IF p_title IS NULL OR LENGTH(TRIM(p_title)) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_title');
  END IF;

  -- ✅ Creator prize pool is capped at what the match's own entry fees can
  -- plausibly cover (max_slots * entry_fee) so a creator can never promise
  -- payouts beyond what their own small-stakes match actually collects.
  v_prize_pool := COALESCE(p_first_prize,0) + COALESCE(p_second_prize,0) + COALESCE(p_third_prize,0);
  IF v_prize_pool > (p_max_slots * p_entry_fee) THEN
    RETURN jsonb_build_object('success', false, 'error', 'prize_exceeds_pool', 'max', p_max_slots * p_entry_fee);
  END IF;
  IF p_first_prize < 0 OR p_second_prize < 0 OR p_third_prize < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_prize');
  END IF;

  SELECT COUNT(*) INTO v_open_count
  FROM matches WHERE creator_uid = v_uid AND status IN ('upcoming', 'live');
  IF v_open_count >= v_max_open THEN
    RETURN jsonb_build_object('success', false, 'error', 'too_many_open_matches', 'max', v_max_open);
  END IF;

  v_match_id := 'cm_' || gen_random_uuid()::TEXT;

  -- ✅ BUG FIX (2026-08-24): "Match create nahi ho paya" for EVERY
  -- creator match attempt, no matter the input. Root cause: matches.name
  -- is a GENERATED ALWAYS column (derived from title) — Postgres hard-
  -- rejects any INSERT that explicitly supplies a value for it
  -- ("cannot insert a non-DEFAULT value into column \"name\"", error
  -- 428C9). The old INSERT explicitly listed `name` with `TRIM(p_title)`
  -- as its value — guaranteed to fail on every single call, for every
  -- creator, regardless of any of the validation above. Confirmed live
  -- via a direct simulated call. Just don't list `name` at all — it
  -- fills itself in from `title` automatically.
  -- ✅ Also added: first_prize/second_prize/third_prize, prize_pool,
  -- and prize_type — the same fields admin's own match-creation form
  -- has, now available to creators too (validated above against the
  -- match's own max possible collected entry fees).
  INSERT INTO matches (
    id, title, mode, entry_type, entry_fee, max_slots, filled_slots,
    per_kill_prize, status, scheduled_at, creator_uid, match_sub_type, created_at,
    first_prize, second_prize, third_prize, prize_pool, prize_type
  ) VALUES (
    v_match_id, TRIM(p_title), p_mode, p_entry_type, p_entry_fee, p_max_slots, 0,
    COALESCE(p_per_kill_prize, 0), 'upcoming', p_scheduled_at, v_uid, 'creator_hosted', NOW(),
    COALESCE(p_first_prize,0), COALESCE(p_second_prize,0), COALESCE(p_third_prize,0), v_prize_pool,
    /* ⛔ B2 (2026-10-06): 'sky_diamond' ENTRY wale match ka prize bhi pehle
         prize_type='sky_diamond' ban jata tha — aur publish ke waqt wo
         users ko Sky Diamond credit kar deta (jo allowed nahi: SD real
         money se juda hai, uska hisaab admin approval + ledger se chalta
         hai). Ab SD-entry match ka prize_type 'green_diamond' hota hai —
         bilkul jaise admin ke paid match ka (SD entry -> GD prize). */
         CASE WHEN p_entry_type = 'coins' THEN 'coins'
              ELSE 'green_diamond' END  /* D87: GD-entry branch removed; prize GD reh sakta hai */
  );

  /* ✅ BUG FIX (2026-10-04): commission SIRF creator-hosted SKY DIAMOND match
     par — jahan koi user sky diamond kharch kare (user ki exact requirement).
     Coin / green_diamond entry matches par KOI commission nahi. Percentage
     admin-set (creator_system.sdMatchCommissionPct) — single source of truth.
     commission_type: 'inr' = payout ledger path, 'none' = no commission. */
  IF p_entry_type = 'sky_diamond' THEN
    v_comm_pct := COALESCE((SELECT (value->>'sdMatchCommissionPct')::numeric FROM app_settings WHERE key='creator_system' LIMIT 1), 15);
    INSERT INTO creator_matches (match_id, creator_uid, commission_pct, commission_type, commission_status, created_at)
    VALUES (v_match_id, v_uid, v_comm_pct, 'inr', 'pending', NOW());
  ELSE
    INSERT INTO creator_matches (match_id, creator_uid, commission_pct, commission_type, commission_status, created_at)
    VALUES (v_match_id, v_uid, 0, 'none', 'pending', NOW());
  END IF;

  INSERT INTO notifications(user_id, type, title, body)
  SELECT follower_uid, 'creator_new_match',
    '🎮 ' || COALESCE(v_creator_ign, 'Creator') || ' ne naya match banaya!',
    TRIM(p_title) || ' — Entry: ' || p_entry_fee || (CASE WHEN p_entry_type='coins' THEN ' coins' ELSE ' 💎' END)
  FROM creator_follows WHERE creator_uid = v_uid;

  GET DIAGNOSTICS v_follower_count = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'match_id', v_match_id, 'notified_followers', v_follower_count);
END;

DECLARE
  v_uid TEXT := auth.jwt() ->> 'sub';
  v_owner TEXT;
  v_status TEXT;
  v_max_slots INT;
  v_per_kill NUMERIC;
  v_entry_type TEXT;
  v_total_kills INT;
  v_winner_uid TEXT;
  v_recent_wins INT;
  v_total_payout NUMERIC := 0;
  v_flag_reason TEXT;
  v_ledger_currency TEXT;
  v_max_payout_cap CONSTANT NUMERIC := 500;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
  SELECT creator_uid, status, max_slots, per_kill_prize, entry_type
    INTO v_owner, v_status, v_max_slots, v_per_kill, v_entry_type
    FROM matches WHERE id = p_match_id;
  IF v_owner IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'match_not_found'); END IF;
  IF v_owner <> v_uid THEN RETURN jsonb_build_object('success', false, 'error', 'not_your_match'); END IF;
  IF v_status <> 'live' THEN RETURN jsonb_build_object('success', false, 'error', 'match_not_live'); END IF;

  IF EXISTS(SELECT 1 FROM users WHERE id = v_uid AND (creator_suspended_permanently = true OR (creator_suspended_until IS NOT NULL AND creator_suspended_until > NOW()))) THEN
    RETURN jsonb_build_object('success', false, 'error', 'creator_suspended');
  END IF;

  /* FIX (R3): 'r' variable vs alias ambiguity — alias ab 'res'.
     Exception-handler bhi: fail par match 'live' atka na rahe. */
  UPDATE join_requests jr
  SET kills = COALESCE((res->>'kills')::INT, 0),
      placement = COALESCE((res->>'placement')::INT, 0)
  FROM jsonb_array_elements(p_results) res
  WHERE jr.id = (res->>'join_request_id')::UUID AND jr.match_id = p_match_id;

  SELECT COALESCE(SUM(kills),0) INTO v_total_kills FROM join_requests WHERE match_id = p_match_id;
  IF v_total_kills > GREATEST(v_max_slots - 1, 1) * 1.5 THEN
    v_flag_reason := 'impossible_kill_count';
  END IF;

  IF v_flag_reason IS NULL THEN
    SELECT user_id INTO v_winner_uid FROM join_requests WHERE match_id = p_match_id AND placement = 1 LIMIT 1;
    IF v_winner_uid IS NOT NULL THEN
      SELECT COUNT(*) INTO v_recent_wins
      FROM creator_matches cm
      JOIN join_requests jr2 ON jr2.match_id = cm.match_id
      WHERE cm.creator_uid = v_uid AND jr2.user_id = v_winner_uid AND jr2.placement = 1
        AND cm.created_at > NOW() - INTERVAL '7 days';
      IF v_recent_wins >= 3 THEN
        v_flag_reason := 'repeat_winner_pattern';
      END IF;
    END IF;
  END IF;

  v_total_payout := v_total_kills * COALESCE(v_per_kill, 0);
  IF v_total_payout > v_max_payout_cap THEN
    v_flag_reason := COALESCE(v_flag_reason, 'payout_cap_exceeded');
  END IF;

  IF v_flag_reason IS NOT NULL THEN
    UPDATE matches SET status = 'pending_review', completed_at = NOW() WHERE id = p_match_id;
    INSERT INTO creator_result_flags(match_id, creator_uid, reason, details)
    VALUES (p_match_id, v_uid, v_flag_reason, jsonb_build_object('total_kills', v_total_kills, 'total_payout', v_total_payout, 'winner_uid', v_winner_uid));
    RETURN jsonb_build_object('success', true, 'status', 'pending_review', 'flagged', true);
  END IF;

  /* SSOT (2026-09-23c): canonical ledger currency — 'sky_diamond' →
     'sky_diamonds' (plural), system-wide canonical. Amount UNCHANGED. */
  v_ledger_currency := CASE WHEN v_entry_type = 'sky_diamond' THEN 'sky_diamonds' ELSE v_entry_type END;

  IF v_per_kill > 0 THEN
    IF v_entry_type = 'coins' THEN
      UPDATE users u SET coins = coins + (jr.kills * v_per_kill)
      FROM join_requests jr WHERE jr.match_id = p_match_id AND jr.user_id = u.id AND jr.kills > 0;
    ELSE
      UPDATE users u SET sky_diamonds = sky_diamonds + (jr.kills * v_per_kill)
      FROM join_requests jr WHERE jr.match_id = p_match_id AND jr.user_id = u.id AND jr.kills > 0;
    END IF;
    INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, ref_id)
    SELECT user_id, v_ledger_currency, 'credit', kills * v_per_kill, 'creator_match_prize', p_match_id
    FROM join_requests WHERE match_id = p_match_id AND kills > 0;
  END IF;

  UPDATE matches SET status = 'completed', completed_at = NOW() WHERE id = p_match_id;
  PERFORM finalize_creator_commission(p_match_id, true);

  RETURN jsonb_build_object('success', true, 'status', 'completed', 'flagged', false);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', 'publish_failed', 'detail', SQLERRM);
END;

DECLARE
  v_me TEXT := auth.jwt() ->> 'sub';
  v_m RECORD; v_friend RECORD; v_my_name TEXT; v_col TEXT; v_bal NUMERIC; v_gift_id UUID;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'Not authorized'); END IF;
  IF p_to_uid IS NULL OR p_to_uid = v_me THEN RETURN jsonb_build_object('ok', false, 'error', 'Apne aap ko gift nahi kar sakte'); END IF;
  /* R6: FOR UPDATE — concurrent gifts same match par capacity race नहीं करते */
  SELECT id, entry_fee, entry_type, name, status, max_slots, filled_slots
    INTO v_m FROM matches WHERE id::text = p_match_id FOR UPDATE;
  IF v_m.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'Match not found'); END IF;
  IF COALESCE(v_m.entry_fee, 0) <= 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'Gift sirf paid matches par'); END IF;
  SELECT id, COALESCE(ff_uid, '') AS ff_uid INTO v_friend FROM users WHERE id = p_to_uid;
  IF v_friend.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'Player not found'); END IF;
  SELECT COALESCE(ign, 'Player') INTO v_my_name FROM users WHERE id = v_me;
  v_col := CASE WHEN lower(COALESCE(v_m.entry_type, 'coin')) = 'coin' THEN 'coins' ELSE 'sky_diamonds' END;

  EXECUTE format('SELECT COALESCE(%I, 0) FROM users WHERE id = $1 FOR UPDATE', v_col) INTO v_bal USING v_me;
  IF v_bal IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'User not found'); END IF;
  IF v_bal < v_m.entry_fee THEN RETURN jsonb_build_object('ok', false, 'error', 'Insufficient balance'); END IF;
  EXECUTE format('UPDATE users SET %I = COALESCE(%I, 0) - $1 WHERE id = $2', v_col, v_col) USING v_m.entry_fee, v_me;

  INSERT INTO gift_tickets (from_uid, from_name, to_uid, to_ff_uid, match_id, match_name, fee, entry_type, status)
  VALUES (v_me, v_my_name, p_to_uid, v_friend.ff_uid, v_m.id, v_m.name, v_m.entry_fee, v_m.entry_type, 'pending')
  RETURNING id INTO v_gift_id;
  INSERT INTO wallet_transactions (user_id, currency, txn_type, amount, reason)
  VALUES (v_me, v_col, 'debit', v_m.entry_fee, 'gift_entry');

  IF v_m.status = 'upcoming' THEN
    IF NOT EXISTS (SELECT 1 FROM join_requests WHERE user_id = p_to_uid AND match_id = v_m.id AND status NOT IN ('cancelled','refunded','no_show')) THEN
      IF COALESCE(v_m.filled_slots, 0) < COALESCE(v_m.max_slots, 999) THEN
        INSERT INTO join_requests (match_id, user_id, status, entry_type, entry_fee_paid, user_ign, ign_at_join, user_ff_uid)
        VALUES (v_m.id, p_to_uid, 'pending', v_m.entry_type, 0,
                (SELECT COALESCE(ign,'Player') FROM users WHERE id = p_to_uid),
                (SELECT COALESCE(ign,'Player') FROM users WHERE id = p_to_uid),
                v_friend.ff_uid);
        UPDATE matches SET filled_slots = COALESCE(filled_slots,0) + 1 WHERE id = v_m.id;
      END IF;
    END IF;
  END IF;
  INSERT INTO notifications (user_id, type, title, body)
  VALUES (p_to_uid, 'gift_ticket', '🎁 Match Ticket Gift!', v_my_name || ' ne tumhe "' || v_m.name || '" ka entry ticket gift kiya!')
  ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('ok', true, 'gift_id', v_gift_id, 'fee', v_m.entry_fee);
END;

DECLARE
  v_caller       TEXT := auth.jwt() ->> 'sub';
  v_m            RECORD;
  v_fee_mode     TEXT;
  v_server_fee   NUMERIC;
  v_slots        INT;
  v_captain_fee  NUMERIC;
  v_member_fee   NUMERIC;
  v_total_collected NUMERIC := 0;
  v_available    INT;
  v_mem          JSONB;
  v_mem_uid      TEXT;
  v_mem_ign      TEXT;
  v_mem_ff_uid   TEXT;
  v_slot_num     INT;
  v_bal          NUMERIC;
  v_col          TEXT;
  v_jr_id        UUID;
  v_idx          INT := 0;
  v_unique_uids  TEXT[] := ARRAY[]::TEXT[];
  v_creator_code TEXT;
  v_creator_uid  TEXT;
  v_commission_pct NUMERIC;
  v_commission   NUMERIC;
  v_first_row_id UUID;
  v_authorized   BOOLEAN;
  v_team         JSONB := '[]'::jsonb;
  v_auto_squad   BOOLEAN := false;
  v_team_id_for_as TEXT;
  v_q            RECORD;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  IF p_mode IS NULL THEN p_mode := 'solo'; END IF;
  p_mode := lower(p_mode);
  v_slots := CASE WHEN p_mode = 'duo' THEN 2 WHEN p_mode = 'squad' THEN 4 ELSE 1 END;

  IF p_fee_type IS NULL THEN p_fee_type := 'captain_pays'; END IF;
  p_fee_type := lower(p_fee_type);
  IF p_fee_type NOT IN ('captain_pays','each_pays','solo') THEN p_fee_type := 'captain_pays'; END IF;
  IF v_slots = 1 THEN p_fee_type := 'solo'; END IF;

  SELECT id, status, entry_type, entry_fee, max_slots, filled_slots, creator_uid
    INTO v_m
    FROM matches
   WHERE id = p_match_id
     FOR UPDATE;
  IF v_m.id IS NULL THEN RAISE EXCEPTION 'MATCH_NOT_FOUND'; END IF;
  IF v_m.status IS DISTINCT FROM 'upcoming' AND v_m.status IS DISTINCT FROM 'live' THEN
    RAISE EXCEPTION 'MATCH_NOT_JOINABLE';
  END IF;
  IF v_m.creator_uid IS NOT NULL AND v_m.creator_uid = v_caller THEN
    RAISE EXCEPTION 'SELF_PLAY_BLOCKED';
  END IF;

  CASE COALESCE(lower(regexp_replace(v_m.entry_type, '[_ -]', '', 'g')), 'free')
    WHEN 'coin'  THEN v_server_fee := COALESCE(v_m.entry_fee,0); v_fee_mode := 'coins';
    WHEN 'paid'  THEN v_server_fee := COALESCE(v_m.entry_fee,0); v_fee_mode := 'sky_diamonds';
    WHEN 'skydiamond' THEN v_server_fee := COALESCE(v_m.entry_fee,0); v_fee_mode := 'sky_diamonds';
    /* ✅ MATCH-FLOW-E2E FIX (2026-10-30): 'greendiamond'/'skydiamond' branches
       missing the — green_diamond match ka TEAM fee ELSE branch se SKY wallet
       se kat raha tha (live proof: run 40986675005 MF19, tx currency=sky_diamonds
       amount=40 green match ke liye). validate_and_join_match (solo) me ye fix
       2026-10-04 ko ho chuka tha; team path reh gaya tha. */
    WHEN 'greendiamond' THEN v_server_fee := COALESCE(v_m.entry_fee,0); v_fee_mode := 'green_diamonds';
    WHEN 'free'  THEN v_server_fee := 0; v_fee_mode := 'free';
    WHEN 'ad'    THEN v_server_fee := 0; v_fee_mode := 'ad';
    ELSE
      IF COALESCE(v_m.entry_fee,0) > 0 THEN v_server_fee := v_m.entry_fee; v_fee_mode := 'sky_diamonds';
      ELSE v_server_fee := 0; v_fee_mode := 'free'; END IF;
  END CASE;
  v_col := CASE WHEN v_fee_mode = 'coins' THEN 'coins' WHEN v_fee_mode = 'green_diamonds' THEN 'green_diamonds' ELSE 'sky_diamonds' END;

  IF v_slots >= 2 AND (p_team IS NULL OR jsonb_typeof(p_team) <> 'array' OR jsonb_array_length(p_team) = 0) THEN
    SELECT team_id INTO v_team_id_for_as
      FROM auto_squad_queue
     WHERE match_id = p_match_id AND user_id = v_caller
       AND status = 'matched' AND mode = p_mode AND team_id IS NOT NULL
     FOR UPDATE;
    IF v_team_id_for_as IS NULL THEN
      RAISE EXCEPTION 'AUTO_SQUAD_NO_MATCH';
    END IF;
    v_auto_squad := true;
    p_fee_type := 'each_pays';
    FOR v_q IN
      SELECT aq.user_id AS uid, COALESCE(u.ign, aq.ign, 'Player') AS ign
        FROM auto_squad_queue aq
        LEFT JOIN users u ON u.id = aq.user_id
       WHERE aq.match_id = p_match_id AND aq.team_id = v_team_id_for_as
         AND aq.status = 'matched' AND aq.mode = p_mode
       ORDER BY (aq.user_id = v_caller) DESC, aq.rank_pts DESC, aq.joined_at ASC
       FOR UPDATE OF aq
    LOOP
      v_team := v_team || jsonb_build_object('uid', v_q.uid, 'ign', v_q.ign);
    END LOOP;
    IF jsonb_array_length(v_team) <> v_slots THEN
      RAISE EXCEPTION 'AUTO_SQUAD_INCOMPLETE';
    END IF;
  ELSE
    IF p_team IS NULL OR jsonb_typeof(p_team) <> 'array' OR jsonb_array_length(p_team) = 0 THEN
      RAISE EXCEPTION 'INVALID_TEAM';
    END IF;
    v_team := p_team;
  END IF;

  v_mem := v_team -> 0;
  IF (v_mem->>'uid') IS NULL OR (v_mem->>'uid') <> v_caller THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  IF jsonb_array_length(v_team) <> v_slots THEN
    RAISE EXCEPTION 'TEAM_SIZE_MISMATCH';
  END IF;

  v_captain_fee := CASE WHEN p_fee_type = 'each_pays' THEN v_server_fee
                        ELSE v_server_fee * v_slots END;
  v_member_fee := CASE WHEN p_fee_type = 'each_pays' THEN v_server_fee ELSE 0 END;

  v_available := COALESCE(v_m.max_slots, 999) - COALESCE(v_m.filled_slots, 0);
  IF v_available < v_slots THEN RAISE EXCEPTION 'MATCH_FULL'; END IF;

  FOR v_idx IN 0 .. jsonb_array_length(v_team) - 1 LOOP
    v_mem := v_team -> v_idx;
    v_mem_uid := v_mem->>'uid';
    IF v_mem_uid IS NULL OR v_mem_uid = ANY(v_unique_uids) THEN
      RAISE EXCEPTION 'INVALID_TEAM';
    END IF;
    v_unique_uids := v_unique_uids || v_mem_uid;
    IF COALESCE((SELECT is_banned FROM users WHERE id = v_mem_uid), false) THEN
      RAISE EXCEPTION 'ACCOUNT_BANNED';
    END IF;
    IF EXISTS(SELECT 1 FROM join_requests
              WHERE user_id = v_mem_uid AND match_id = p_match_id
                AND status NOT IN ('cancelled','refunded','no_show')) THEN
      RAISE EXCEPTION 'ALREADY_JOINED';
    END IF;

    IF v_idx >= 1 AND NOT v_auto_squad THEN
      v_authorized := EXISTS(
        SELECT 1 FROM team_invitations ti
        WHERE ti.match_id    = p_match_id
          AND ti.captain_uid = v_caller
          AND ti.member_uid  = v_mem_uid
          AND ti.status      = 'accepted'
          AND ti.mode        = p_mode
          AND ti.fee_type    = p_fee_type
      );
      IF NOT v_authorized THEN
        v_authorized := EXISTS(
          SELECT 1 FROM auto_squad_queue my
          JOIN auto_squad_queue them
            ON them.match_id = my.match_id
           AND them.team_id  = my.team_id
         WHERE my.match_id   = p_match_id
           AND my.user_id    = v_caller
           AND my.status     = 'matched'
           AND my.mode       = p_mode
           AND them.user_id  = v_mem_uid
           AND them.status   = 'matched'
           AND them.mode     = p_mode
           AND my.team_id IS NOT NULL
           AND COALESCE(my.fee_type, them.fee_type, 'each_pays') = p_fee_type
        );
      END IF;
      IF NOT v_authorized THEN
        IF EXISTS(
          SELECT 1 FROM team_invitations ti
          WHERE ti.match_id = p_match_id
            AND ti.captain_uid = v_caller
            AND ti.member_uid = v_mem_uid
            AND ti.status = 'accepted'
        ) THEN
          RAISE EXCEPTION 'TEAM_TERMS_MISMATCH';
        END IF;
        RAISE EXCEPTION 'TEAM_NOT_AUTHORIZED';
      END IF;
    END IF;
  END LOOP;

  IF v_server_fee > 0 THEN
    FOR v_idx IN 0 .. jsonb_array_length(v_team) - 1 LOOP
      v_mem := v_team -> v_idx;
      v_mem_uid := v_mem->>'uid';
      IF v_col = 'coins' THEN
        SELECT coins INTO v_bal FROM users WHERE id = v_mem_uid FOR UPDATE;
      ELSIF v_col = 'green_diamonds' THEN
        SELECT green_diamonds INTO v_bal FROM users WHERE id = v_mem_uid FOR UPDATE;
      ELSE
        SELECT sky_diamonds INTO v_bal FROM users WHERE id = v_mem_uid FOR UPDATE;
      END IF;
      IF v_bal IS NULL THEN RAISE EXCEPTION 'USER_NOT_FOUND'; END IF;
      IF v_idx = 0 THEN
        IF v_bal < v_captain_fee THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE'; END IF;
      ELSE
        IF v_bal < v_member_fee THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE'; END IF;
      END IF;
    END LOOP;
  END IF;

  FOR v_idx IN 0 .. jsonb_array_length(v_team) - 1 LOOP
    v_mem := v_team -> v_idx;
    v_mem_uid := v_mem->>'uid';
    SELECT
      COALESCE(NULLIF(v_mem->>'ign', ''), u.ign, ''),
      COALESCE(NULLIF(v_mem->>'ffUid', ''), u.ff_uid, '')
    INTO v_mem_ign, v_mem_ff_uid
    FROM users u
    WHERE u.id = v_mem_uid;

    v_mem_ign := COALESCE(v_mem_ign, '');
    v_mem_ff_uid := COALESCE(v_mem_ff_uid, '');
    v_slot_num := COALESCE(v_m.filled_slots, 0) + v_idx + 1;

    IF v_idx = 0 THEN v_bal := v_captain_fee; ELSE v_bal := v_member_fee; END IF;

    IF v_server_fee > 0 AND v_bal > 0 THEN
      IF v_col = 'coins' THEN
        UPDATE users SET coins = coins - v_bal WHERE id = v_mem_uid;
      ELSIF v_col = 'green_diamonds' THEN
        UPDATE users SET green_diamonds = green_diamonds - v_bal WHERE id = v_mem_uid;
      ELSE
        UPDATE users SET sky_diamonds = sky_diamonds - v_bal WHERE id = v_mem_uid;
      END IF;
      INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, ref_id)
      VALUES (v_mem_uid, v_fee_mode, 'debit', v_bal, 'match_entry', p_match_id);
      v_total_collected := v_total_collected + v_bal;
    END IF;

    INSERT INTO join_requests(
      user_id, match_id, entry_fee, entry_fee_paid, entry_type,
      status, mode, ign_at_join, user_ign, user_ff_uid, slot_number, fee_type, captain_uid
    )
    VALUES(
      v_mem_uid, p_match_id, v_bal, v_bal,
      CASE WHEN v_fee_mode='coins' THEN 'coin'
           WHEN v_fee_mode='sky_diamonds' THEN 'sky_diamond'
           WHEN v_fee_mode='green_diamonds' THEN 'green_diamond'
           ELSE COALESCE(v_m.entry_type,'free') END,
      'joined', p_mode, v_mem_ign, v_mem_ign, v_mem_ff_uid, v_slot_num, p_fee_type,
      CASE WHEN v_idx = 0 THEN NULL ELSE v_caller END
    ) RETURNING id INTO v_jr_id;
    IF v_idx = 0 THEN v_first_row_id := v_jr_id; END IF;
  END LOOP;

  UPDATE matches SET filled_slots = COALESCE(filled_slots, 0) + v_slots WHERE id = p_match_id;

  IF v_fee_mode = 'sky_diamonds' AND v_total_collected > 0 THEN
    SELECT creator_code INTO v_creator_code FROM users WHERE id = v_caller;
    IF v_creator_code IS NOT NULL THEN
      SELECT user_id INTO v_creator_uid FROM creator_codes WHERE code = v_creator_code;
      IF v_creator_uid IS NOT NULL AND v_creator_uid <> v_caller
         AND EXISTS(SELECT 1 FROM users WHERE id = v_creator_uid AND is_creator = true) THEN
        SELECT COALESCE((value->>'sdMatchCommissionPct')::numeric, 15)
          INTO v_commission_pct FROM app_settings WHERE key = 'creator_system';
        v_commission_pct := COALESCE(v_commission_pct, 15);
        v_commission := ROUND(v_total_collected * v_commission_pct / 100, 2);
        INSERT INTO creator_stats(user_id, total_matches, total_earnings)
        VALUES (v_creator_uid, 1, v_commission)
        ON CONFLICT (user_id) DO UPDATE SET
          total_matches = creator_stats.total_matches + 1,
          total_earnings = creator_stats.total_earnings + v_commission, updated_at = NOW();
        INSERT INTO creator_commissions(creator_uid, match_id, amount, currency, status, eligible_at)
        VALUES (v_creator_uid, p_match_id, v_commission, 'inr', 'hold', NOW() + INTERVAL '7 days');
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'captain_row_id', v_first_row_id, 'slots', v_slots);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'code', SQLERRM, 'error',
      CASE SQLERRM
        WHEN 'NOT_AUTHORIZED'        THEN 'Not authorized'
        WHEN 'TEAM_NOT_AUTHORIZED'   THEN 'Teammates ne join authorize nahi kiya — pehle team invite accept karwao'
        WHEN 'TEAM_TERMS_MISMATCH'   THEN 'Invite ke terms match nahi — invite me jo mode/fee-type thi wahi chun ke join karo'
        WHEN 'AUTO_SQUAD_NO_MATCH'   THEN 'Tumhari koi matched auto-squad team nahi hai'
        WHEN 'AUTO_SQUAD_INCOMPLETE' THEN 'Auto-squad team abhi poori nahi hui'
        WHEN 'MATCH_NOT_FOUND'       THEN 'Match not found'
        WHEN 'MATCH_NOT_JOINABLE'    THEN 'Match ab join nahi ho sakta'
        WHEN 'SELF_PLAY_BLOCKED'     THEN 'Apne khud ke hosted match mein join nahi kar sakte'
        WHEN 'ACCOUNT_BANNED'        THEN 'Kisi teammate ka account ban hai'
        WHEN 'ALREADY_JOINED'        THEN 'Koi teammate already is match mein join hai'
        WHEN 'MATCH_FULL'            THEN 'Match full ho gaya'
        WHEN 'INSUFFICIENT_BALANCE'  THEN 'Kisi teammate ke paas balance kam hai'
        WHEN 'USER_NOT_FOUND'        THEN 'Player not found'
        WHEN 'TEAM_SIZE_MISMATCH'    THEN 'Team size galat hai'
        WHEN 'INVALID_TEAM'          THEN 'Team invalid hai'
        ELSE SQLERRM
      END);
END;

DECLARE
  v_caller      TEXT := auth.jwt() ->> 'sub';
  v_is_service  BOOLEAN := (current_setting('role', true) = 'service_role');
  v_is_admin    BOOLEAN;
  v_m           RECORD;
  v_name        TEXT;
  v_currency    TEXT;          -- coins | sky_diamonds | green_diamonds
  v_curr_label  TEXT;
  v_is_corr     BOOLEAN;
  v_first       NUMERIC; v_second NUMERIC; v_third NUMERIC; v_perk NUMERIC; v_entry NUMERIC;
  item          jsonb;
  v_uid         TEXT; v_rank INT; v_kills INT;
  v_join        RECORD;
  v_rank_prize  NUMERIC; v_kill_prize NUMERIC; v_total NUMERIC;
  v_cap         TEXT;          -- jisko paisa credit hoga (captain_pays member → captain)
  v_earn        NUMERIC;       -- is uid ka effective money
  v_capagg      jsonb := '{}'::jsonb;  -- target_uid -> total money
  v_plist       jsonb := '[]'::jsonb;  -- [{uid,rank,kills,cap}]
  v_old         jsonb := '{}'::jsonb;  -- target -> old prize_earned
  v_oldkills    jsonb := '{}'::jsonb;  -- uid -> old kills
  k             TEXT;
  v_delta       NUMERIC;
  v_kill_delta  INT;
  v_rp          INT;
  v_is_winner   BOOLEAN;
  v_month       TEXT := to_char((now() AT TIME ZONE 'Asia/Kolkata')::date, 'YYYY_MM');
  v_pub         INT := 0; v_corr INT := 0; v_skip INT := 0; v_win_n INT := 0;
BEGIN
  /* ── Authorization ── */
  IF NOT v_is_service THEN
    IF v_caller IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Admin only');
    END IF;
    SELECT is_admin INTO v_is_admin FROM users WHERE id = v_caller;
    IF NOT COALESCE(v_is_admin, false) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Admin only');
    END IF;
  END IF;

  IF jsonb_typeof(p_results) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_results must be an array');
  END IF;

  SELECT * INTO v_m FROM matches WHERE id = p_match_id FOR UPDATE;
  IF v_m.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'MATCH_NOT_FOUND');
  END IF;

  v_name       := COALESCE(v_m.name, v_m.title, p_match_id);
  v_is_corr    := (v_m.result_published_at IS NOT NULL);
  v_first      := COALESCE(v_m.first_prize, 0);
  v_second     := COALESCE(v_m.second_prize, 0);
  v_third      := COALESCE(v_m.third_prize, 0);
  v_perk       := COALESCE(v_m.per_kill_prize, 0);
  v_entry      := COALESCE(v_m.entry_fee, 0);

  /* ⛔ B2 (2026-10-06) — "Sky Diamond prize me KABHI nahi diya jata":
     yahan pehle ek branch tha jo prize_type IN ('sky','sky_diamond',
     'skyDiamond') par users.sky_diamonds CREDIT kar deta tha. Sky Diamond
     real money se juda hua hai (uski distribution admin ke approval +
     ledger se hoti hai), isliye prize me dena economy ka hisaab bigaadta
     hai. Ab wo branch hata diya: aise (purane) matches ka prize
     Green Diamonds me jata hai — aaj ke admin form ka niyam bhi yahi hai
     (paid / SD-entry match => prize Green Diamond). */
  IF COALESCE(v_m.prize_type,'') IN ('green_diamond','greenDiamond') THEN
    v_currency := 'green_diamonds'; v_curr_label := 'Green Diamonds';
  ELSIF COALESCE(v_m.prize_type,'') IN ('sky','sky_diamond','skyDiamond') THEN
    v_currency := 'green_diamonds'; v_curr_label := 'Green Diamonds';
  ELSIF COALESCE(v_m.prize_type,'') IN ('coin','coins','cash') THEN
    v_currency := 'coins'; v_curr_label := 'Coins';
  ELSE
    IF v_m.entry_type IN ('paid','sky_diamond','skyDiamond') THEN
      v_currency := 'green_diamonds'; v_curr_label := 'Green Diamonds';
    ELSE
      v_currency := 'coins'; v_curr_label := 'Coins';
    END IF;
  END IF;

  /* ⛔ B2 HARD GUARD (2026-10-06): is function se prize ke roop me Sky
     Diamond KABHI credit na ho — chahe upar ki koi bhi shaakh (branch) ho
     ya future me koi naya prize_type aaye. (wallet_transactions me bhi
     isliye hamesha coins/green_diamonds hi jayega.) */
  IF v_currency = 'sky_diamonds' THEN
    v_currency := 'green_diamonds'; v_curr_label := 'Green Diamonds';
  END IF;

  /* ── Pass 1: compute prizes + captain aggregation (server-authoritative) ── */
  FOR item IN SELECT jsonb_array_elements(p_results) LOOP
    v_uid  := item->>'user_id';
    v_rank := GREATEST(COALESCE((item->>'rank')::int, 0), 0);
    v_kills := GREATEST(COALESCE((item->>'kills')::int, 0), 0);
    IF v_uid IS NULL OR v_uid = '' THEN v_skip := v_skip + 1; CONTINUE; END IF;

    SELECT * INTO v_join FROM join_requests
    WHERE match_id = p_match_id AND user_id = v_uid;
    IF v_join IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;

    v_rank_prize := CASE WHEN v_rank = 1 THEN v_first
                         WHEN v_rank = 2 THEN v_second
                         WHEN v_rank = 3 THEN v_third
                         ELSE 0 END;
    v_kill_prize := v_kills * v_perk;
    v_total      := v_rank_prize + v_kill_prize;

    /* captain_pays member → paisa captain ko */
    v_cap := v_uid;
    IF v_join.fee_type = 'captain_pays'
       AND v_join.captain_uid IS NOT NULL
       AND v_join.captain_uid <> v_uid THEN
      v_cap := v_join.captain_uid;
    END IF;

    v_capagg := jsonb_set(v_capagg, ARRAY[v_cap],
      to_jsonb(COALESCE((v_capagg->>v_cap)::numeric, 0) + v_total), true);

    v_plist := v_plist || jsonb_build_object(
      'uid', v_uid, 'rank', v_rank, 'kills', v_kills, 'cap', v_cap);
  END LOOP;

  /* ── Pass 0 (read olds BEFORE any write) ── */
  FOR k IN SELECT jsonb_object_keys(v_capagg) LOOP
    SELECT COALESCE(prize_earned, 0) INTO v_delta
      FROM match_results WHERE match_id = p_match_id AND user_id = k;
    v_old := jsonb_set(v_old, ARRAY[k], to_jsonb(v_delta), true);
  END LOOP;
  FOR item IN SELECT * FROM jsonb_array_elements(v_plist) LOOP
    SELECT COALESCE(kills, 0) INTO v_kill_delta
      FROM match_results WHERE match_id = p_match_id AND user_id = (item->>'uid');
    v_oldkills := jsonb_set(v_oldkills, ARRAY[item->>'uid'], to_jsonb(v_kill_delta), true);
  END LOOP;

  /* ── Pass 2: money per target (credit / correction delta) ── */
  FOR k IN SELECT jsonb_object_keys(v_capagg) LOOP
    v_total := (v_capagg->>k)::numeric;
    v_delta := v_total - COALESCE((v_old->>k)::numeric, 0);

    IF v_is_corr THEN
      IF v_delta <> 0 THEN
        IF v_currency = 'coins' THEN
          UPDATE users SET coins = GREATEST(COALESCE(coins,0) + v_delta, 0),
                           total_winnings = GREATEST(COALESCE(total_winnings,0) + v_delta, 0)
          WHERE id = k;
        ELSIF v_currency = 'sky_diamonds' THEN
          UPDATE users SET sky_diamonds = GREATEST(COALESCE(sky_diamonds,0) + v_delta, 0),
                           total_winnings = GREATEST(COALESCE(total_winnings,0) + v_delta, 0)
          WHERE id = k;
        ELSE
          UPDATE users SET green_diamonds = GREATEST(COALESCE(green_diamonds,0) + v_delta, 0),
                           total_winnings = GREATEST(COALESCE(total_winnings,0) + v_delta, 0)
          WHERE id = k;
        END IF;
        INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, status, ref_id, created_at)
        VALUES (k, v_currency,
                CASE WHEN v_delta > 0 THEN 'correction_credit' ELSE 'correction_debit' END,
                ABS(v_delta), 'result_correction', 'approved', p_match_id, NOW());

        INSERT INTO notifications(user_id, type, title, body, is_read, created_at, ref_id)
        VALUES (k, 'correction',
                '🔧 Result Correction',
                v_name || ' — ' || ABS(v_delta) || ' ' || v_curr_label || ' ' ||
                CASE WHEN v_delta > 0 THEN 'add kiya gaya.' ELSE 'adjust kiya gaya.' END,
                false, NOW(), p_match_id);
        v_corr := v_corr + 1;
      END IF;
    ELSE
      IF v_total > 0 THEN
        IF v_currency = 'coins' THEN
          UPDATE users SET coins = COALESCE(coins,0) + v_total,
                           total_winnings = COALESCE(total_winnings,0) + v_total
          WHERE id = k;
        ELSIF v_currency = 'sky_diamonds' THEN
          UPDATE users SET sky_diamonds = COALESCE(sky_diamonds,0) + v_total,
                           total_winnings = COALESCE(total_winnings,0) + v_total
          WHERE id = k;
        ELSE
          UPDATE users SET green_diamonds = COALESCE(green_diamonds,0) + v_total,
                           total_winnings = COALESCE(total_winnings,0) + v_total
          WHERE id = k;
        END IF;
        INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, status, ref_id, created_at)
        VALUES (k, v_currency, 'match_win', v_total, 'match_prize', 'approved', p_match_id, NOW());
        v_win_n := v_win_n + 1;
      END IF;
    END IF;
  END LOOP;

  /* ── Pass 3: per-player stats + match_results + join_requests + notifications ── */
  FOR item IN SELECT * FROM jsonb_array_elements(v_plist) LOOP
    v_uid   := item->>'uid';
    v_rank  := (item->>'rank')::int;
    v_kills := (item->>'kills')::int;
    v_earn  := COALESCE((v_capagg->>v_uid)::numeric, 0);   -- member -> 0
    v_is_winner := v_earn > 0;

    IF NOT v_is_corr THEN
      v_rp := CASE WHEN v_rank = 1 THEN 25 WHEN v_rank = 2 THEN 15
                   WHEN v_rank = 3 THEN 10 WHEN v_rank <= 10 THEN 5 ELSE 1 END
              + LEAST(v_kills, 3);
      IF NOT v_is_winner THEN v_rp := 1; END IF;

      UPDATE users SET
        total_kills   = COALESCE(total_kills,0) + v_kills,
        total_matches = COALESCE(total_matches,0) + 1,
        total_wins    = COALESCE(total_wins,0) + CASE WHEN v_is_winner AND v_rank = 1 THEN 1 ELSE 0 END,
        win_streak    = CASE WHEN v_is_winner THEN COALESCE(win_streak,0) + 1 ELSE 0 END,
        rank_points   = COALESCE(rank_points,0) + v_rp
      WHERE id = v_uid;

      INSERT INTO season_stats(month_key, user_id, kills, matches, wins)
      VALUES (v_month, v_uid, v_kills, 1, CASE WHEN v_rank = 1 THEN 1 ELSE 0 END)
      ON CONFLICT (month_key, user_id) DO UPDATE SET
        kills   = season_stats.kills + EXCLUDED.kills,
        matches = season_stats.matches + 1,
        wins    = season_stats.wins + EXCLUDED.wins,
        updated_at = NOW();

      IF v_is_winner THEN
        INSERT INTO notifications(user_id, type, title, body, is_read, created_at, ref_id)
        VALUES (v_uid, 'result', '🏆 Match Result!',
                v_name || ' — jeete! ' || v_earn || ' ' || v_curr_label ||
                ' wallet mein add ho gaye. (Rank #' || v_rank || ', ' || v_kills || ' kills)',
                false, NOW(), p_match_id);
      ELSE
        INSERT INTO notifications(user_id, type, title, body, is_read, created_at, ref_id)
        VALUES (v_uid, 'result', '📋 Match Result',
                v_name || ' ka result publish ho gaya! Rank: #' || v_rank ||
                ', Kills: ' || v_kills || '.',
                false, NOW(), p_match_id);
      END IF;

      /* platform earnings (first publish only) — entry fee server-side */
      INSERT INTO platform_earnings(match_id, entry_fee, prize_given, profit, user_id)
      VALUES (p_match_id, v_entry, v_earn, v_entry - v_earn, v_uid);

    ELSE
      /* correction: sirf kills delta (money delta upar target-loop me) */
      v_kill_delta := v_kills - COALESCE((v_oldkills->>v_uid)::int, 0);
      IF v_kill_delta <> 0 THEN
        UPDATE users SET total_kills = GREATEST(COALESCE(total_kills,0) + v_kill_delta, 0)
        WHERE id = v_uid;
      END IF;
    END IF;

    /* match_results (authoritative result row) */
    INSERT INTO match_results(match_id, user_id, placement, kills, rank,
                              kill_prize, rank_prize, prize_earned, prize)
    VALUES (p_match_id, v_uid, v_rank, v_kills, v_rank,
            v_kills * v_perk,
            CASE WHEN v_rank = 1 THEN v_first WHEN v_rank = 2 THEN v_second
                 WHEN v_rank = 3 THEN v_third ELSE 0 END,
            v_earn, v_earn)
    ON CONFLICT (match_id, user_id) DO UPDATE SET
      placement   = EXCLUDED.placement,
      kills       = EXCLUDED.kills,
      rank        = EXCLUDED.rank,
      kill_prize  = EXCLUDED.kill_prize,
      rank_prize  = EXCLUDED.rank_prize,
      prize_earned = EXCLUDED.prize_earned,
      prize       = EXCLUDED.prize;

    /* join_requests final state */
    UPDATE join_requests SET status = 'completed', placement = v_rank,
                             prize_earned = v_earn, kills = v_kills
    WHERE match_id = p_match_id AND user_id = v_uid;

    v_pub := v_pub + 1;
  END LOOP;

  /* matches → completed + result_published_at (idempotent) */
  UPDATE matches SET status = 'completed', updated_at = NOW(),
                     result_published_at = COALESCE(result_published_at, NOW())
  WHERE id = p_match_id;

  RETURN jsonb_build_object(
    'ok', true,
    'players', v_pub,
    'winners', v_win_n,
    'corrections', v_corr,
    'currency', v_currency,
    'was_correction', v_is_corr,
    'skipped', v_skip);
END;

DECLARE
  v_m              RECORD;
  v_balance        NUMERIC;
  v_joined         BOOLEAN := false;
  v_jr_id          UUID;
  v_fee_mode       TEXT;
  v_server_fee     NUMERIC;
  v_slots          INT;
  v_charge_fee     NUMERIC;
  v_available      INT;
  v_caller         TEXT := auth.jwt() ->> 'sub';
  v_host_uid       TEXT;
  v_commission     NUMERIC;
  v_commission_pct NUMERIC;
  v_hold_days      NUMERIC;
  v_ign            TEXT;
  v_ff_uid         TEXT;
  v_slot_num       INT;
BEGIN
  IF v_caller IS NULL OR v_caller <> p_uid THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  SELECT id, title, status, entry_type, entry_fee, max_slots, filled_slots, creator_uid
    INTO v_m
    FROM matches
   WHERE id = p_match_id
     FOR UPDATE;
  IF v_m.id IS NULL THEN
    RAISE EXCEPTION 'MATCH_NOT_FOUND';
  END IF;

  IF v_m.status IS DISTINCT FROM 'upcoming' AND v_m.status IS DISTINCT FROM 'live' THEN
    RAISE EXCEPTION 'MATCH_NOT_JOINABLE';
  END IF;

  IF v_m.creator_uid IS NOT NULL AND v_m.creator_uid = p_uid THEN
    RAISE EXCEPTION 'SELF_PLAY_BLOCKED';
  END IF;

  IF COALESCE((SELECT is_banned FROM users WHERE id = p_uid), false) THEN
    RAISE EXCEPTION 'ACCOUNT_BANNED';
  END IF;

  /* ✅ BUG FIX (2026-10-04): "coin entry fee wale creator match mein bhi
     user se sky_diamond katta tha". Root cause: CASE sirf 'coin' match
     karta tha, lekin DB mein entry_type 'coins' (plural) save hota hai
     (creator_create_match 'coins' deta hai) — plural ELSE branch mein
     gir kar sky_diamonds charge kar deta tha. Ab dono forms handle. */
  CASE COALESCE(lower(regexp_replace(v_m.entry_type, '[_ -]', '', 'g')), 'free')
    WHEN 'coin' THEN
      v_server_fee := COALESCE(v_m.entry_fee, 0);
      v_fee_mode   := 'coins';
    WHEN 'coins' THEN
      v_server_fee := COALESCE(v_m.entry_fee, 0);
      v_fee_mode   := 'coins';
    WHEN 'paid' THEN
      v_server_fee := COALESCE(v_m.entry_fee, 0);
      v_fee_mode   := 'sky_diamonds';
    WHEN 'skydiamond' THEN
      v_server_fee := COALESCE(v_m.entry_fee, 0);
      v_fee_mode   := 'sky_diamonds';
    /* ✅ BUG FIX (2026-10-04): green_diamond entry support (creator price type) */
    WHEN 'greendiamond' THEN
      /* ✅ D87 (owner): Green Diamond ENTRY abolished — legacy GD-entry
         match free join hota hai (GD se fee kabhi nahi kat-ti). */
      v_server_fee := 0; v_fee_mode := 'free';
    WHEN 'free' THEN
      v_server_fee := 0; v_fee_mode := 'free';
    WHEN 'ad' THEN
      v_server_fee := 0; v_fee_mode := 'ad';
    ELSE
      IF COALESCE(v_m.entry_fee, 0) > 0 THEN
        v_server_fee := v_m.entry_fee; v_fee_mode := 'sky_diamonds';
      ELSE
        v_server_fee := 0; v_fee_mode := 'free';
      END IF;
  END CASE;

  v_slots := 1;
  IF p_join_data IS NOT NULL AND p_join_data ? 'mode' THEN
    IF p_join_data->>'mode' = 'duo'  THEN v_slots := 2; END IF;
    IF p_join_data->>'mode' = 'squad' THEN v_slots := 4; END IF;
  END IF;

  v_charge_fee :=
    CASE
      WHEN v_slots = 1 THEN v_server_fee
      WHEN (p_join_data->>'feeType') = 'each_pays' THEN v_server_fee
      ELSE v_server_fee * v_slots
    END;

  IF v_server_fee > 0 THEN
    IF v_fee_mode = 'coins' THEN
      SELECT coins INTO v_balance FROM users WHERE id = p_uid FOR UPDATE;
    ELSE
      SELECT sky_diamonds INTO v_balance FROM users WHERE id = p_uid FOR UPDATE;
    END IF;
    IF v_balance IS NULL THEN RAISE EXCEPTION 'USER_NOT_FOUND'; END IF;
    IF v_balance < v_charge_fee THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE'; END IF;
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM join_requests
    WHERE user_id = p_uid AND match_id = p_match_id
      AND status NOT IN ('cancelled','refunded','no_show')
  ) INTO v_joined;
  IF v_joined THEN RAISE EXCEPTION 'ALREADY_JOINED'; END IF;

  v_available := COALESCE(v_m.max_slots, 999) - COALESCE(v_m.filled_slots, 0);
  IF v_available < v_slots THEN RAISE EXCEPTION 'MATCH_FULL'; END IF;

  IF v_server_fee > 0 THEN
    IF v_fee_mode = 'coins' THEN
      UPDATE users SET coins = coins - v_charge_fee WHERE id = p_uid;
    ELSE
      UPDATE users SET sky_diamonds = sky_diamonds - v_charge_fee WHERE id = p_uid;
    END IF;
    INSERT INTO wallet_transactions(user_id, currency, txn_type, amount, reason, ref_id)
    VALUES(p_uid, v_fee_mode, 'debit', v_charge_fee, 'match_entry', p_match_id);
  END IF;

  SELECT
    COALESCE(NULLIF(p_join_data->>'ign', ''), NULLIF(p_join_data->>'userName', ''), u.ign, ''),
    COALESCE(NULLIF(p_join_data->>'userFFUID', ''), NULLIF(p_join_data->>'ffUid', ''), u.ff_uid, '')
  INTO v_ign, v_ff_uid
  FROM users u
  WHERE u.id = p_uid;

  v_ign := COALESCE(v_ign, '');
  v_ff_uid := COALESCE(v_ff_uid, '');
  v_slot_num := COALESCE(v_m.filled_slots, 0) + 1;

  INSERT INTO join_requests(
    user_id, match_id, entry_fee, entry_fee_paid, entry_type,
    status, mode, ign_at_join, user_ign, user_ff_uid, slot_number, fee_type
  )
  VALUES(
    p_uid, p_match_id, v_charge_fee, v_charge_fee,
    CASE WHEN v_fee_mode='coins' THEN 'coin'
         WHEN v_fee_mode='sky_diamonds' THEN 'sky_diamond'
         ELSE COALESCE(v_m.entry_type, 'free') END,
    'joined',
    COALESCE(p_join_data->>'mode', 'solo'),
    v_ign,
    v_ign,
    v_ff_uid,
    v_slot_num,
    COALESCE(p_join_data->>'feeType', 'solo')
  ) RETURNING id INTO v_jr_id;

  UPDATE matches SET filled_slots = COALESCE(filled_slots, 0) + v_slots WHERE id = p_match_id;

  /* ✅ BUG FIX (2026-10-04): DOUBLE-COMMISSION FIX. Pehle yahan (join-time)
     bhi creator_commissions row insert hoti thi, AUR finalize_creator_commission
     (match end) par bhi total se ek aur row — creator ko ek hi match ki
     commission DO BAAR milti thi. Ab commission ka SINGLE source of truth
     sirf finalize_creator_commission hai (match end par, actual paid entries
     ka sum × admin-set pct). Yahan koi commission insert NAHI hota. */

  RETURN jsonb_build_object('ok', true, 'jr_id', v_jr_id::TEXT);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error',
      CASE SQLERRM
        WHEN 'NOT_AUTHORIZED'       THEN 'Not authorized'
        WHEN 'MATCH_NOT_FOUND'      THEN 'Match not found'
        WHEN 'MATCH_NOT_JOINABLE'   THEN 'Match ab join nahi ho sakta'
        WHEN 'USER_NOT_FOUND'       THEN 'User not found'
        WHEN 'INSUFFICIENT_BALANCE' THEN 'Balance kam hai'
        WHEN 'ALREADY_JOINED'       THEN 'Aap already join ho chuke ho'
        WHEN 'MATCH_FULL'           THEN 'Match full ho gaya'
        WHEN 'SELF_PLAY_BLOCKED'    THEN 'Apne khud ke hosted match mein join nahi kar sakte'
        WHEN 'ACCOUNT_BANNED'       THEN 'Aapka account ban hai'
        ELSE SQLERRM
      END
    );
END;
